theorem Compatible.trans {m M : Type*} [Field m] [Field M] [Algebra m M] {τ : L ≃+* M}
    (hσ : Compatible (k := k) (l := l) σ) (hτ : Compatible (k := l) (l := m) τ) :
    Compatible (k := k) (l := m) (σ.trans τ)

theorem aeval_eq_aeval_of_idealOf_eq {a b : ι → Ω}
    (h : idealOf k a = idealOf k b) {f g : MvPolynomial ι k}
    (hfg : aeval a f = aeval a g) : aeval b f = aeval b g

theorem idealOf_eq_of_aeval_iff {a b : ι → Ω}
    (H : ∀ f : MvPolynomial ι k, aeval a f = 0 ↔ aeval b f = 0) :
    idealOf k a = idealOf k b

theorem IsAdditive.pow_exponent_of_monomial (p : ℕ) [CharP K p] (hp : p.Prime)
    [Infinite K] {P : Polynomial K} (hP : IsAdditive P) {l : K} {m : ℕ}
    (hl : l ≠ 0) (hPm : P = C l * X ^ m) : ∃ r, m = p ^ r

theorem idealOf_swap_span {u v : Ω} {F : MvPolynomial (Fin 2) k}
    (h : idealOf k ![u, v] = Ideal.span {F}) :
    idealOf k ![v, u] = Ideal.span {rename (Equiv.swap (0 : Fin 2) 1) F}

theorem joint_aeval_eq_zero {c : Fin 2 → K} {q : Fin 2 → Ω}
    {G : MvPolynomial (Fin 2) k}
    (hspan : idealOf K q = Ideal.span {MvPolynomial.map (algebraMap k K) G})
    {w : Fin 2 → Ω} (hw : aeval w G = 0)
    {f : MvPolynomial (Fin 2 ⊕ Fin 2) k}
    (hf : aeval (Sum.elim (fun j ↦ algebraMap K Ω (c j)) q) f = 0) :
    aeval (Sum.elim (fun j ↦ algebraMap K Ω (c j)) w) f = 0

theorem joint_aeval_eq_zero' {c : Fin 2 → K} {p q : Fin 2 → Ω}
    (hp : (fun j ↦ algebraMap K Ω (c j)) = p)
    {G : MvPolynomial (Fin 2) k}
    (hspan : idealOf K q = Ideal.span {MvPolynomial.map (algebraMap k K) G})
    {w : Fin 2 → Ω} (hw : aeval w G = 0)
    {f : MvPolynomial (Fin 2 ⊕ Fin 2) k}
    (hf : aeval (Sum.elim p q) f = 0) :
    aeval (Sum.elim p w) f = 0

theorem mem_span_C_iff {R : Type*} [CommRing R] {g : R}
    {p : MvPolynomial (Fin 2) R} :
    p ∈ Ideal.span {(C g : MvPolynomial (Fin 2) R)} ↔
      ∀ m, p.coeff m ∈ Ideal.span {g}

theorem isNilpotent_of_forall_algHom_eq_zero {k S : Type*} [Field k] [IsAlgClosed k]
    [CommRing S] [Algebra k S] [Algebra.FiniteType k S] {z : S}
    (hz : ∀ φ : S →ₐ[k] k, φ z = 0) : IsNilpotent z

theorem exists_sub_C_mem_of_pow_sub_one_mem [IsAlgClosed k] {σ : Type*}
    {J : Ideal (MvPolynomial σ k)} (hJ : J.IsPrime) (M : MvPolynomial σ k) {n : ℕ}
    (hn : n ≠ 0) (hM : M ^ n - 1 ∈ J) : ∃ ζ : k, M - C ζ ∈ J

theorem two_le_ringKrullDim_quotient {R : Type*} [CommRing R] {P p₁ p₂ : Ideal R}
    [P.IsPrime] [p₁.IsPrime] [p₂.IsPrime] (h₁ : P < p₁) (h₂ : p₁ < p₂) :
    (2 : WithBot ℕ∞) ≤ ringKrullDim (R ⧸ P)

theorem idealOf_aeval_comp_eq_of_idealOf_eq {ι κ : Type*} {a b : ι → K}
    (h : idealOf k a = idealOf k b) (g : κ → MvPolynomial ι k) :
    idealOf k (fun j ↦ aeval a (g j)) = idealOf k (fun j ↦ aeval b (g j))

theorem zpow_left_injective_of_lt_one {Γ : Type*}
    [LinearOrderedCommGroupWithZero Γ] {a : Γ} (h0 : 0 < a) (h1 : a < 1)
    {m n : ℤ} (h : a ^ m = a ^ n) : m = n

theorem isAlgebraic_div_sq_of_isWeightedHomogeneous {F : MvPolynomial (Fin 2) M} {W : ℕ}
    (hF0 : F ≠ 0) (hF : F.IsWeightedHomogeneous ![2, 1] W) {s u : Ω} (hu : u ≠ 0)
    (hsu : MvPolynomial.aeval ![s, u] F = 0) : IsAlgebraic M (s / u ^ 2)

theorem exists_sub_valuation_lt_one_of_mem_adjoin
    (hk : ∀ c : k, algebraMap k F c ∈ O) {x : F}
    (hxtr : Transcendental k x) (hx : O.valuation x < 1) {a : F}
    (ha : a ∈ adjoin k ({x} : Set F)) (hav : O.valuation a ≤ 1) :
    ∃ c : k, O.valuation (a - algebraMap k F c) < 1

theorem linearIndependent_pow_of_transcendental {f : F}
    (htr : Transcendental k f) (N : ℕ) :
    LinearIndependent k fun j : Fin N ↦ f ^ (j : ℕ)

theorem almostLE_map_closure_of {A : Submodule k V}
    {s : Set (Module.End k V)}
    (hs : ∀ w ∈ s, AlmostLE (A.map w) A) :
    ∀ w ∈ Submonoid.closure s, AlmostLE (A.map w) A

theorem pow_eq_zero_of_comp_self_eq_zero {θ : Module.End k V}
    (hθ : θ ∘ₗ θ = 0) {n : ℕ} (hn : 2 ≤ n) :
    (θ ^ n : Module.End k V) = 0

theorem trace_eq_zero_of_isNilpotent {W : Type*} [AddCommGroup W]
    [Module k W] [FiniteDimensional k W] {φ : Module.End k W}
    (h : IsNilpotent φ) : LinearMap.trace k W φ = 0

theorem adjoin_image_eq_top_of_adjoin_eq_top {t : F}
    (htop : adjoin k ({t} : Set F) = ⊤) (σ : F ≃ₐ[k] F) :
    adjoin k ({σ t} : Set F) = ⊤

theorem moebius_det_ne_zero_of_transcendental {z w : F}
    (hw : Transcendental k w) {a b c d : k}
    (hden : algebraMap k F c * z + algebraMap k F d ≠ 0)
    (hrel : w * (algebraMap k F c * z + algebraMap k F d) =
      algebraMap k F a * z + algebraMap k F b) :
    a * d - b * c ≠ 0

theorem frobeniusZPow_sub_apply_of_pow_eq {u v : ℕ} {x y : K}
    (h : y ^ q ^ v = x ^ q ^ u) :
    frobeniusZPow K q ((u : ℤ) - v) x = y

theorem exists_intermediateField_eq_of_subset_iUnion {k F : Type*}
    [Field k] [Field F] [Algebra k F] {n : ℕ}
    {E : IntermediateField k F} {S : Fin n → IntermediateField k F}
    (hle : ∀ i, S i ≤ E) (hcov : (E : Set F) ⊆ ⋃ i, (S i : Set F)) :
    ∃ i, S i = E

theorem indepOver_base_union_iff {C A B E : Set K}
    (hE : IndepOver k ∅ E (C ∪ (A ∪ B))) :
    IndepOver k C A B ↔ IndepOver k (C ∪ E) A B

theorem not_isConstructibleOver_range_algebraMap [Infinite k] {t : K}
    (ht : t ∉ range (algebraMap k K)) :
    ¬ IsConstructibleOver k {u : Fin 1 → K | u 0 ∈ range (algebraMap k K)}

theorem not_isConstructibleOver_setOf_exists_natDegree_le_one [Infinite k] {t : K}
    (ht : t ∉ range (algebraMap k K)) :
    ¬ IsConstructibleOver k {u : Fin 1 → K | ∃ P : Polynomial k, P ≠ 0 ∧ P.natDegree ≤ 1 ∧
      Polynomial.aeval (u 0) P = 0}

theorem setOf_exists_natDegree_le_one_aeval_eq_zero :
    {u : Fin 1 → K | ∃ P : Polynomial k, P ≠ 0 ∧ P.natDegree ≤ 1 ∧ Polynomial.aeval (u 0) P = 0} =
      {u | u 0 ∈ range (algebraMap k K)}

theorem IsConstructibleOver.exists [Finite ι] {κ : Type*} [Finite κ] [IsAlgClosed K]
    {φ : (ι → K) → (κ → K) → Prop}
    (hφ : IsConstructibleOver k {z : (ι ⊕ κ) → K | φ (z ∘ Sum.inl) (z ∘ Sum.inr)}) :
    IsConstructibleOver k {x : ι → K | ∃ y, φ x y}

theorem IsConstructibleOver.forall [Finite ι] {κ : Type*} [Finite κ] [IsAlgClosed K]
    {φ : (ι → K) → (κ → K) → Prop}
    (hφ : IsConstructibleOver k {z : (ι ⊕ κ) → K | φ (z ∘ Sum.inl) (z ∘ Sum.inr)}) :
    IsConstructibleOver k {x : ι → K | ∀ y, φ x y}

theorem IsConstructibleOver.of_le_intermediateField
    {E E' : IntermediateField k K} (h : E ≤ E') {X : Type*} {s : Set (X → K)}
    (hs : IsConstructibleOver (↥E) s) : IsConstructibleOver (↥E') s

theorem IsConstructibleOver.of_restrictScalars_eq {M : IntermediateField k K}
    {E : IntermediateField (↥M) K} {E' : IntermediateField k K}
    (hE : E.restrictScalars k = E') {X : Type*} {s : Set (X → K)} (h : IsConstructibleOver (↥E) s) :
    IsConstructibleOver (↥E') s

theorem IsConstructibleOver.preimage_polynomial {κ : Type*}
    (q : κ → MvPolynomial ι k) {s : Set (κ → K)}
    (hs : IsConstructibleOver k s) :
    IsConstructibleOver k ((fun x i ↦ MvPolynomial.aeval x (q i)) ⁻¹' s)

theorem coordPoly_mem_of_mem_map (l : K →ₗ[R] R) {J : Ideal (MvPolynomial ι R)}
    {f : MvPolynomial ι K} (hf : f ∈ J.map (MvPolynomial.map (algebraMap R K))) :
    coordPoly l f ∈ J

theorem idealDefinedOver_of_span {I : Ideal (MvPolynomial ι K)} {S : Set (MvPolynomial ι K)}
    (hS : Ideal.span S = I) {d : ℕ} (hd : ∀ f ∈ S, f.totalDegree ≤ d)
    (h : DefinedOver (degSubspace I d) F) : IdealDefinedOver F I

theorem mem_map_comap_of_definedOver {I : Ideal (MvPolynomial ι K)} {d : ℕ}
    (h : DefinedOver (degSubspace I d) F) {f : MvPolynomial ι K} (hf : f ∈ I)
    (hfd : f.totalDegree ≤ d) : f ∈ (I.comap (mapF F)).map (mapF F)

theorem eq_of_map_iterateFrobenius_eq (hp : p.Prime) {F : Subfield K}
    (hF : Subfield.relfinrank (F.map (frobenius K p)) F = p) {a b : ℕ}
    (h : F.map (iterateFrobenius K p a) = F.map (iterateFrobenius K p b)) : a = b

theorem exists_eq_map_iterateFrobenius (hp : p.Prime) {F : Subfield K}
    (hF : Subfield.relfinrank (F.map (frobenius K p)) F = p) {E : Subfield K} {n : ℕ}
    (h₁ : F.map (iterateFrobenius K p n) ≤ E) (h₂ : E ≤ F) :
    ∃ j ≤ n, E = F.map (iterateFrobenius K p j)
